    private NguoiTuVan getAdvisorOrThrow(CustomUserDetails userDetails) {
        if (userDetails == null) {
            throw new SecurityException("Vui lòng đăng nhập.");
        }
        return nguoiTuVanRepo.findByTaiKhoan_MaTK(userDetails.getMaTK()).orElseThrow(() -> new IllegalStateException("Không tìm thấy thông tin cố vấn cho tài khoản này."));
    }

    @GetMapping("/dashboard")
    public String dashboard(@AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        NguoiTuVan cv = getAdvisorOrThrow(userDetails);
        List<YeuCauTuVan> myTickets = ticketService.getAdvisorAssignedTickets(cv.getMaCV());
        List<YeuCauTuVan> queue = ticketService.getDepartmentQueue(cv.getDonVi().getMaDonVi());
        List<LichHenTuVan> appointments = appointmentService.getAdvisorAppointments(cv.getMaCV());
        long pendingAppointments = appointments.stream().filter(a -> "ChoDuyet".equals(a.getTrangThai())).count();
        model.addAttribute("advisor", cv);
        model.addAttribute("assignedTickets", myTickets);
        model.addAttribute("queueTickets", queue);
        model.addAttribute("pendingAppointmentsCount", pendingAppointments);
        model.addAttribute("appointments", appointments.stream().limit(5).toList());
        model.addAttribute("notifications", notificationService.getUserNotifications(cv.getTaiKhoan().getMaTK()).stream().limit(5).toList());
        return "advisor/dashboard";
    }

    @GetMapping("/tickets")
    public String tickets(@AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        NguoiTuVan cv = getAdvisorOrThrow(userDetails);
        model.addAttribute("advisor", cv);
        model.addAttribute("assignedTickets", ticketService.getAdvisorAssignedTickets(cv.getMaCV()));
        model.addAttribute("closedTickets", ticketService.getAdvisorClosedTickets(cv.getMaCV()));
        model.addAttribute("queueTickets", ticketService.getDepartmentQueue(cv.getDonVi().getMaDonVi()));
        return "advisor/tickets";
    }

    @PostMapping("/tickets/{id}/claim")
    public String claimTicket(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            ticketService.claimTicket(id, cv);
            redirectAttributes.addFlashAttribute("successMessage", "Bạn đã tiếp nhận câu hỏi diễn đàn thành công!");
            return "redirect:/advisor/tickets/" + id;
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
            return "redirect:/advisor/tickets";
        }
    }

    @GetMapping("/tickets/{id}")
    public String ticketDetail(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        NguoiTuVan cv = getAdvisorOrThrow(userDetails);
        YeuCauTuVan ticket;
        try {
            ticket = ticketService.getAdvisorTicket(id, cv);
        } catch (SecurityException e) {
            return "redirect:/advisor/tickets";
        }
        if (ticket == null) {
            return "redirect:/advisor/tickets";
        }
        model.addAttribute("ticket", ticket);
        model.addAttribute("advisor", cv);
        model.addAttribute("mauTraLoiList", catalogService.getMauTraLoiByDonVi(cv.getDonVi().getMaDonVi()));
        model.addAttribute("donViList", catalogService.getAllActiveDonVi());
        model.addAttribute("linhVucList", catalogService.getAllActiveLinhVuc());
        addTicketAttachments(model, ticket);
        return "advisor/ticket-detail";
    }

    @PostMapping("/tickets/{id}/reply")
    public String replyTicket(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String noiDung, @RequestParam(required = false) Boolean deXuatFaq, @RequestParam(required = false) MultipartFile attachment, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            PhanHoiTuVan reply = submissions.reply(id, cv, noiDung, deXuatFaq, attachment);
            redirectAttributes.addFlashAttribute("successMessage", "Đã gửi câu trả lời tư vấn thành công!");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/advisor/tickets/" + id;
    }

    @PostMapping("/tickets/{id}/transfer")
    public String transferTicket(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam Integer maDonViMoi, @RequestParam Integer maLinhVucMoi, @RequestParam String lyDo, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            ticketService.transferTicket(id, maDonViMoi, maLinhVucMoi, lyDo, cv);
            redirectAttributes.addFlashAttribute("successMessage", "Đã chuyển tiếp yêu cầu sang đơn vị mới.");
            return "redirect:/advisor/tickets";
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
            return "redirect:/advisor/tickets/" + id;
        }
    }

